// Prompt Injection guide: shared types + authored simulation data.
// Every transcript below is an AUTHORED SIMULATION for defensive education.
// No output is generated by a live model, and the injected instruction is a
// deliberately generic, non-functional example.

export type DefenseId = "none" | "spotlighting" | "gating" | "combined";

export type StepActor = "user" | "agent" | "tool" | "guard";

export type StepTone = "neutral" | "danger" | "warning" | "success";

export interface ScenarioStep {
  actor: StepActor;
  title: string;
  text: string;
  tone: StepTone;
  /** Marks the step that surfaces the smuggled instruction (highlighted in UI). */
  showsInjection?: boolean;
}

export interface DefenseMeta {
  id: DefenseId;
  label: string;
  short: string;
  /** Qualitative, illustrative risk after this defense. 0 = lowest, 3 = highest. */
  riskLevel: 0 | 1 | 2 | 3;
  riskLabel: string;
  honestNote: string;
}

export interface InboxEmail {
  id: string;
  from: string;
  subject: string;
  body: string;
  /** The embedded instruction, rendered highlighted. Benign and illustrative. */
  injectedLine?: string;
}

