// ── Builder checklist ────────────────────────────────────────────────────────

export const CHECKLIST_ITEMS: { title: string; detail: string }[] = [
  {
    title: "Treat all retrieved and tool content as untrusted",
    detail:
      "Webpages, emails, documents, and tool results are attacker-reachable input, never instructions.",
  },
  {
    title: "Gate consequential actions on human approval",
    detail:
      "Sending, deleting, paying, and publishing should require explicit confirmation, enforced outside the model.",
  },
  {
    title: "Give agents least-privilege tools",
    detail:
      "An assistant that only needs to read and summarize should not hold a send or delete capability at all.",
  },
  {
    title: "Log and review agent actions",
    detail:
      "Every tool call should be auditable so a successful injection is detected fast, not months later.",
  },
  {
    title: "Red-team your own agent",
    detail:
      "Plant benign test instructions in the content your agent reads and verify they are never followed.",
  },
];
